// <diletta-input-chip> — a INSTÂNCIA WEB de `design-system-input-chip`.
//
// A primeira peça web que COMPÕE outra peça web: com `entity="person"` ela
// instancia `<diletta-avatar>`. É o que a linguagem promete dos dois lados — o
// Dart compõe `DilettaAvatar`, e aqui compõe o custom element, não um círculo
// desenhado de novo.
import './diletta-avatar.js';
import { papeisDe, estiloDa, eixo } from './base.js';

const SLUG = 'design-system-input-chip';
const STATUS = ['normal', 'hover', 'pressed', 'disabled'];
const SIZE = ['md', 'sm'];
const ENTITY = ['general', 'person'];

// Da spec, e são medidas e não gosto: `md` tem 32 de altura, `sm` tem 24, e o
// selecionável em `sm` mantém 26. O alvo de toque de 44 fica FORA do desenho.
const ALTURA = { md: 32, sm: 24 };
const ALVO = 44;

const X = '<svg viewBox="0 0 16 16" aria-hidden="true" focusable="false">' +
  '<path d="M4 4l8 8M12 4l-8 8" stroke="currentColor" stroke-width="1.5" ' +
  'stroke-linecap="round"/></svg>';

class DilettaInputChip extends HTMLElement {
  static observedAttributes = ['status', 'size', 'entity', 'label', 'foto', 'removivel'];

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }

  connectedCallback() {
    this.render();
  }

  attributeChangedCallback() {
    if (this.shadowRoot) this.render();
  }

  render() {
    const status = eixo(this, 'status', STATUS, 'normal');
    const size = eixo(this, 'size', SIZE, 'sm');
    const entity = eixo(this, 'entity', ENTITY, 'general');
    const papeis = papeisDe(SLUG, { Status: status });
    const label = this.getAttribute('label') || '';
    const off = status === 'disabled';
    const h = ALTURA[size];

    // `entity: person` GANHA do leadIcon — a spec: *"dois acessórios iniciais na
    // mesma pílula não é escolha"*. Aqui isso é estrutural: só um dos dois é
    // renderizado, e a decisão não sobra para quem chama.
    const inicio = entity === 'person'
      ? `<diletta-avatar nome="${label.replace(/"/g, '&quot;')}" letras="1" ` +
        `foto="${(this.getAttribute('foto') || '').replace(/"/g, '&quot;')}" ` +
        `style="--diletta-avatar-tamanho:16px"></diletta-avatar>`
      : '<slot name="lead"></slot>';

    this.shadowRoot.innerHTML = `
      <style>
        /* O ALVO É MAIOR QUE O DESENHO, e por isso ele mora no :host e não na
           pílula: crescer a pílula até 44 mudaria o desenho que a spec mede em
           24 e 32. É o mesmo arranjo do DilettaAlvoDeToque no Dart. */
        :host {
          display: inline-flex; align-items: center; justify-content: center;
          min-height: ${ALVO}px;
        }
        .pilula {
          ${estiloDa(papeis)}
          box-sizing: border-box;
          height: ${h}px;
          display: inline-flex; align-items: center; gap: 6px;
          padding: 0 ${size === 'md' ? 12 : 8}px;
          border-radius: 999px;
          /* Longhand, e NUNCA o atalho de borda: ele vem depois da pintura e
             reseta a cor que ela acabou de escrever. Medido no navegador em
             06/09 — a peça saía com borderColor rgba(0,0,0,0) e o teste, que lê
             o TEXTO do CSS, não via nada. Atalho depois de longhand apaga em
             silêncio. (Sem crase neste comentário: ele mora dentro de um
             template literal, e crase aqui fecha a string.) */
          border-width: 1px; border-style: solid; border-color: transparent;
          font-size: var(--cps-type-caption-size, 12px);
          cursor: ${off ? 'default' : 'pointer'};
        }
        .remover {
          display: inline-flex; background: none; border-width: 0; padding: 0;
          color: inherit; cursor: inherit;
        }
        .remover svg { width: 12px; height: 12px; }
        .pilula:focus-visible { outline: 3px solid var(--cps-primary); outline-offset: 2px; }
      </style>
      <div class="pilula" part="pilula" role="button" tabindex="${off ? -1 : 0}"
           aria-disabled="${off}">
        ${inicio}<span class="rotulo">${label}</span>
        ${this.hasAttribute('removivel')
          ? `<button class="remover" type="button" aria-label="Remover ${label}">${X}</button>`
          : ''}
      </div>`;
  }
}

customElements.define('diletta-input-chip', DilettaInputChip);
export { DilettaInputChip, ALTURA, ALVO };
